"""Isolated per-job media worker. Paths are generated by the Node server, never URL input."""
import importlib.util
import json
import math
import os
import re
import subprocess
import sys
from pathlib import Path
from urllib.parse import urlparse, parse_qs


def ffmpeg():
    import imageio_ffmpeg
    return os.environ.get('FFMPEG_BIN') or imageio_ffmpeg.get_ffmpeg_exe()


def rects(raw, width, height):
    if not isinstance(raw, list) or not 1 <= len(raw) <= 12:
        raise ValueError('Mark 1–12 small regions to clean.')
    result = []
    area = 0
    for r in raw:
        if len(r) != 4 or not all(isinstance(v, (int,float)) and math.isfinite(v) for v in r):
            raise ValueError('Invalid selection.')
        x,y,w,h=r
        if not (0 <= x < 1 and 0 <= y < 1 and w > 0 and h > 0 and x+w <= 1.001 and y+h <= 1.001):
            raise ValueError('Selection must be inside the image.')
        area += w*h
        result.append((int(x*width),int(y*height),min(width,int(math.ceil((x+w)*width))),min(height,int(math.ceil((y+h)*height)))))
    if area > .25:
        raise ValueError('Select less than 25% of the picture. Large removals cannot be reconstructed reliably.')
    return result


def inpaint(image, regions):
    import cv2
    import numpy as np
    result=image.copy()
    for x,y,x2,y2 in rects(regions,image.shape[1],image.shape[0]):
        left=max(0,x-25);top=max(0,y-25);right=min(image.shape[1],x2+25);bottom=min(image.shape[0],y2+25)
        patch=result[top:bottom,left:right].copy()
        mask=np.zeros(patch.shape[:2],dtype=np.uint8);mask[y-top:y2-top,x-left:x2-left]=255
        result[top:bottom,left:right]=cv2.inpaint(patch,mask,3,cv2.INPAINT_TELEA)
    return result


def clean_image(job):
    import cv2
    import numpy as np
    from PIL import Image,ImageOps
    Image.MAX_IMAGE_PIXELS=20_000_000
    with Image.open(job['input']) as source:
        if source.width*source.height > 20_000_000: raise ValueError('Image limit: 20 megapixels.')
        image=ImageOps.exif_transpose(source).convert('RGBA')
        pixels=np.array(image)
    cleaned=inpaint(cv2.cvtColor(pixels[:,:,:3],cv2.COLOR_RGB2BGR),job['regions'])
    rgba=np.dstack([cv2.cvtColor(cleaned,cv2.COLOR_BGR2RGB),pixels[:,:,3]])
    Image.fromarray(rgba).save(job['output'],format='PNG')
    return {'name':'cleaned-image.png','mime':'image/png'}


def clean_pdf(job):
    import pymupdf as fitz
    import numpy as np
    import cv2
    with fitz.open(job['input']) as source,fitz.open() as output:
        if source.needs_pass or not 1 <= len(source) <= 30: raise ValueError('Use an unlocked PDF with 1–30 pages.')
        selected=int(job.get('page',0));all_pages=bool(job.get('allPages'))
        if not 0 <= selected < len(source):raise ValueError('Page is out of range.')
        for i,p in enumerate(source):
            if not all_pages and i!=selected:
                output.insert_pdf(source,from_page=i,to_page=i);continue
            if max(p.rect.width,p.rect.height)>2000:raise ValueError('PDF page is too large.')
            pix=p.get_pixmap(matrix=fitz.Matrix(1.5,1.5),alpha=False)
            pixels=np.frombuffer(pix.samples,dtype=np.uint8).reshape(pix.height,pix.width,pix.n)
            cleaned=inpaint(cv2.cvtColor(pixels,cv2.COLOR_RGB2BGR),job['regions'])
            ok,png=cv2.imencode('.png',cleaned)
            if not ok:raise ValueError('Could not encode PDF page.')
            dest=output.new_page(width=p.rect.width,height=p.rect.height)
            dest.insert_image(dest.rect,stream=png.tobytes())
        output.set_metadata({})
        output.save(job['output'],garbage=4,deflate=True)
    return {'name':'cleaned-document.pdf','mime':'application/pdf'}


def clean_video(job):
    import cv2
    cap=cv2.VideoCapture(job['input'])
    fps=cap.get(cv2.CAP_PROP_FPS);frames=int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
    ok,first=cap.read()
    if not ok:raise ValueError('Cannot decode this video. Try an MP4 with H.264 video.')
    height,width=first.shape[:2]
    if not 1<=fps<=60 or frames<=0 or frames/fps>60 or frames>3600 or width*height>1920*1080:
        cap.release();raise ValueError('Video limit: 60 seconds, 1080p, 60 fps.')
    if width%2 or height%2:cap.release();raise ValueError('Use a video with even pixel dimensions for MP4 export.')
    rects(job['regions'],width,height)
    command=[ffmpeg(),'-hide_banner','-loglevel','error','-y','-f','rawvideo','-vcodec','rawvideo','-pix_fmt','bgr24','-s',f'{width}x{height}','-r',str(fps),'-i','pipe:0','-i',job['input'],'-map','0:v:0','-map','1:a:0?','-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-c:a','aac','-movflags','+faststart','-shortest','-f','mp4',job['output']]
    errorfile=Path(job['output']).with_suffix('.log')
    try:
        with errorfile.open('wb') as errors:
            process=subprocess.Popen(command,stdin=subprocess.PIPE,stdout=subprocess.DEVNULL,stderr=errors)
            try:
                import time
                started=time.monotonic()
                current=first;count=0
                while current is not None:
                    count+=1
                    if count>3600:raise ValueError('Too many video frames.')
                    if time.monotonic()-started>180:raise ValueError('Video processing took too long. Try a shorter clip.')
                    process.stdin.write(inpaint(current,job['regions']).tobytes())
                    success,next_frame=cap.read();current=next_frame if success else None
                process.stdin.close()
                if process.wait(timeout=30)!=0:raise ValueError('Video encoding failed.')
            finally:
                if process.poll() is None:process.kill();process.wait()
    finally:cap.release()
    return {'name':'cleaned-video.mp4','mime':'video/mp4'}


def validate_url(value):
    u=urlparse(value)
    if u.scheme!='https' or u.username or u.password or u.port not in (None,443):raise ValueError('Use an HTTPS video URL from YouTube, Instagram or Facebook.')
    host=(u.hostname or '').lower();path=u.path
    youtube=host in ('youtube.com','www.youtube.com','m.youtube.com') and ((path=='/watch' and re.fullmatch(r'[\w-]{11}',parse_qs(u.query).get('v',[''])[0])) or re.fullmatch(r'/(?:shorts|embed)/[\w-]{11}/?',path))
    short=host=='youtu.be' and re.fullmatch(r'/[\w-]{11}/?',path)
    instagram=host in ('instagram.com','www.instagram.com') and re.fullmatch(r'/(?:p|reel|reels)/[\w-]+/?',path)
    facebook=host in ('facebook.com','www.facebook.com','m.facebook.com') and (re.fullmatch(r'/(?:[^/]+/)?videos/\d+/?',path) or re.fullmatch(r'/reel/\d+/?',path) or (path in ('/watch','/watch/') and re.fullmatch(r'\d+',parse_qs(u.query).get('v',[''])[0])))
    if not any((youtube,short,instagram,facebook)):raise ValueError('Paste a direct video/reel link, not a profile, playlist, shortened redirect or arbitrary website.')
    return value


def download(job):
    from yt_dlp import YoutubeDL
    url=validate_url(job['url']);limit=200*1024*1024
    def progress(status):
        if status.get('downloaded_bytes',0)>limit:raise ValueError('Video exceeds the 200 MB download limit.')
    def match(info,*,incomplete=False):
        if info.get('is_live'):return 'Live streams are not supported.'
        if info.get('duration',0) and info['duration']>600:return 'Maximum duration is 10 minutes.'
        if info.get('has_drm'):return 'Protected streams are not supported.'
    class Quiet:
        def debug(self,*args):pass
        def warning(self,*args):pass
        def error(self,*args):pass
    options={'outtmpl':str(Path(job['output']).parent/'download.%(ext)s'),'noplaylist':True,'playlistend':1,'max_downloads':1,'max_filesize':limit,'socket_timeout':15,'retries':1,'fragment_retries':1,'concurrent_fragment_downloads':1,'cachedir':False,'logger':Quiet(),'progress_hooks':[progress],'match_filter':match,'format':'best[height<=720][ext=mp4]/best[height<=720]','ffmpeg_location':ffmpeg(),'restrictfilenames':True,'writethumbnail':False,'writeinfojson':False,'allowed_extractors':['youtube$','instagram$','facebook$'],'js_runtimes':{'node':{}},'enable_file_urls':False,'overwrites':True}
    try:
        with YoutubeDL(options) as ydl:
            info=ydl.extract_info(url,download=True)
            if not info or info.get('_type') in ('playlist','multi_video'):raise ValueError('Use a single public video link.')
        candidates=[p for p in Path(job['output']).parent.glob('download.*') if p.suffix in ('.mp4','.webm','.mkv','.mov')]
        if len(candidates)!=1 or not candidates[0].stat().st_size:raise ValueError('No downloadable public video was available.')
        source=candidates[0]
        if source.stat().st_size>limit:raise ValueError('Video exceeds 200 MB.')
        source.rename(job['output'])
        return {'name':'downloaded-video'+source.suffix,'mime':{'.mp4':'video/mp4','.webm':'video/webm','.mov':'video/quicktime','.mkv':'video/x-matroska'}[source.suffix]}
    except Exception as exc:
        raise ValueError('This platform did not provide an accessible download. The video may require login, be restricted, exceed limits, or need a newer yt-dlp version. No login, DRM or access restriction bypass is attempted.') from exc


def run(job):
    action=job['action']
    if action=='capabilities':
        modules={m:bool(importlib.util.find_spec(m)) for m in ('cv2','pymupdf','yt_dlp','imageio_ffmpeg','PIL')}
        return {'image':modules['cv2'] and modules['PIL'],'pdf':modules['cv2'] and modules['pymupdf'],'video':modules['cv2'] and modules['imageio_ffmpeg'],'download':modules['yt_dlp'] and modules['imageio_ffmpeg']}
    if action=='image':return clean_image(job)
    if action=='pdf':return clean_pdf(job)
    if action=='video':return clean_video(job)
    if action=='download':return download(job)
    raise ValueError('Unsupported media operation.')


if __name__=='__main__':
    try:print(json.dumps({'ok':True,**run(json.load(sys.stdin))}))
    except Exception as e:
        print(json.dumps({'ok':False,'error':str(e)[:700]}));sys.exit(1)
